1	mod band_table;
2	mod bands;
3	mod benches;
4	mod config;
5	mod harness;
6	mod inhibit;
7	mod overhead;
8	mod pin;
9	mod probe;
10	mod ticks;
11	mod tprobe;
12	mod tprobe2;
13	
14	use clap::Parser;
15	use log::{debug, info};
16	
17	#[derive(Parser)]
18	#[command(
19	    version,
20	    about = concat!(
21	        "iiac-perf ",
22	        env!("CARGO_PKG_VERSION"),
23	        " — Rust latency microbenchmark harness",
24	    ),
25	    max_term_width = 80,
26	)]
27	struct Cli {
28	    /// Benches to run. Pass 'all' for every registered bench, or
29	    /// one or more names; a name matching no bench exactly runs
30	    /// every bench it is a prefix of (e.g. 'ice', 'mpsc').
31	    /// Run with no args to see the available list.
32	    benches: Vec<String>,
33	
34	    /// Target wall-clock seconds per bench (default 5.0, or the
35	    /// config `duration`). Auto-sizes outer and inner loop counts.
36	    /// Mutually exclusive with -D.
37	    #[arg(short = 'd', long, conflicts_with = "total_duration")]
38	    duration: Option<f64>,
39	
40	    /// Target total wall-clock seconds across all requested benches;
41	    /// budget is split equally per bench. Mutually exclusive with -d.
42	    #[arg(short = 'D', long)]
43	    total_duration: Option<f64>,
44	
45	    /// Override outer loop count (skips auto-sizing; inner still adapts).
46	    #[arg(short, long)]
47	    outer: Option<u64>,
48	
49	    /// Override inner loop count (skips auto-sizing).
50	    /// inner=1 measures single-call latency (each sample = one step); higher
51	    /// inner measures back-to-back/burst rate (each sample = N steps averaged).
52	    #[arg(short, long)]
53	    inner: Option<u64>,
54	
55	    /// Pin bench threads to logical CPUs (comma-separated, ranges OK).
56	    /// The list is a core *pool*: thread `i` of a bench is pinned to
57	    /// `pool[i % pool.len()]`, so shorter pools oversubscribe by wrap.
58	    /// Examples: `--pin 0,1` (2 threads → 2 CPUs), `--pin 0-5` (6-thread
59	    /// pool), `--pin 0,0` (two threads on the same CPU). On 3900X,
60	    /// logical CPUs N and N+12 are SMT siblings of the same physical
61	    /// core — `--pin 0,12` pairs siblings (max contention), `--pin 0,1`
62	    /// gives independent cores. A value naming a `[profiles]` entry in
63	    /// the config file expands to that profile's core spec (e.g.
64	    /// `--pin smt`). Omit to leave threads unpinned.
65	    #[arg(long, value_name = "CORES")]
66	    pin: Option<String>,
67	
68	    /// Skip pinning the main thread for calibration. Always takes
69	    /// effect, including when `--pin` is set — bench threads still
70	    /// pin per `--pin`, but main stays on whatever affinity mask
71	    /// the process launched with. By default (without this flag),
72	    /// calibration runs with main pinned to `pin[0]` if set, else
73	    /// core 0, so framing/loop come from a stable environment.
74	    /// Pass this flag to decouple the calibration environment from
75	    /// the bench pinning pool (or to reproduce pre-0.6.0 behavior
76	    /// when `--pin` is absent).
77	    #[arg(long)]
78	    no_pin_cal: bool,
79	
80	    /// Enable verbose internals on stderr: affinity mask, cal
81	    /// parameters and raw fit inputs, calibration wall time.
82	    /// Equivalent to `RUST_LOG=debug`. Default is `warn` (silent
83	    /// unless something's wrong). `RUST_LOG` overrides this flag
84	    /// when set, so per-module filtering still works.
85	    #[arg(short, long)]
86	    verbose: bool,
87	
88	    /// Show tprobe results in raw TSC ticks instead of converting
89	    /// to nanoseconds. Only affects `TProbe` output; `Probe`
90	    /// results are always in nanoseconds.
91	    #[arg(short = 't', long)]
92	    ticks: bool,
93	
94	    /// Band label style for the report's histogram rows.
95	    /// 'zpn': nines/zeros + decile names (z3, p50, n4).
96	    /// 'frac': literal boundary fractions with '_' grouping
97	    /// (0.001, 0.50, 0.999_9). 'both': zpn and fraction
98	    /// side by side — the juxtaposition teaches the zpn
99	    /// vocabulary; switch to 'zpn' once fluent. Overrides the
100	    /// config `band_labels`; both absent defaults to 'both'.
101	    #[arg(long, value_enum)]
102	    band_labels: Option<bands::BandLabels>,
103	
104	    /// Decimal digits on the report's time columns (0-3).
105	    /// 1 shows the sub-ns precision picosecond recording
106	    /// captures; 0 restores integer ns; 3 is the recording
107	    /// floor - more digits would be artifacts. Overrides the
108	    /// config `decimals`; both absent defaults to 1.
109	    #[arg(long, value_parser = clap::value_parser!(u8).range(0..=3))]
110	    decimals: Option<u8>,
111	
112	    /// Do not inhibit system sleep for the run. By default the
113	    /// process re-execs itself under `systemd-inhibit --what=sleep`
114	    /// so an idle-suspend can't poison a long measurement. Pass
115	    /// this to keep the process image untouched (strace/gdb/perf
116	    /// wrappers), to let the machine sleep on purpose, or to test
117	    /// the suspend-detection WARNING path (a sleep inhibitor also
118	    /// blocks manual `systemctl suspend`).
119	    #[arg(long)]
120	    no_inhibit: bool,
121	}
122	
123	const DEFAULT_DURATION: f64 = 5.0;
124	const DEFAULT_BAND_LABELS: bands::BandLabels = bands::BandLabels::Both;
125	const DEFAULT_DECIMALS: u8 = 1;
126	
127	/// Banner text listing which config files were loaded, or
128	/// `"none (built-in defaults)"` when neither file exists.
129	fn config_summary(files: &[std::path::PathBuf]) -> String {
130	    if files.is_empty() {
131	        "none (built-in defaults)".to_string()
132	    } else {
133	        files
134	            .iter()
135	            .map(|p| p.display().to_string())
136	            .collect::<Vec<_>>()
137	            .join(", ")
138	    }
139	}
140	
141	fn main() {
142	    let cli = Cli::parse();
143	
144	    // Default filter is `warn`; `-v` bumps to `debug`. `RUST_LOG`
145	    // (if set) always wins — so users can still do fine-grained
146	    // per-module filtering without fighting the flag.
147	    let mut builder = env_logger::Builder::from_default_env();
148	    if std::env::var_os("RUST_LOG").is_none() {
149	        builder.filter_level(if cli.verbose {
150	            log::LevelFilter::Debug
151	        } else {
152	            log::LevelFilter::Warn
153	        });
154	    }
155	    builder.format_timestamp(None).init();
156	
157	    if cli.benches.is_empty() {
158	        println!("no benches specified. use -h or --help for more info.");
159	        println!("available: all, {}", benches::names().join(", "));
160	        return;
161	    }
162	
163	    // Re-exec under systemd-inhibit (unless --no-inhibit or
164	    // already inhibited) before any output, so the banner prints
165	    // once, from the inhibited child.
166	    let inhibit_status = inhibit::ensure(cli.no_inhibit);
167	
168	    // Layered defaults (built-in < XDG file < project-local file <
169	    // CLI). A malformed config is fatal so a typo surfaces.
170	    let (config, config_files) = match config::load() {
171	        Ok(c) => c,
172	        Err(e) => {
173	            eprintln!("error: config: {e}");
174	            std::process::exit(2);
175	        }
176	    };
177	
178	    println!(
179	        "iiac-perf {} — Rust latency microbenchmark harness\n",
180	        env!("CARGO_PKG_VERSION")
181	    );
182	
183	    if let Some(mask) = pin::current_affinity() {
184	        info!("startup affinity: {}", pin::affinity_summary(&mask));
185	    }
186	
187	    let pin_cores: Vec<usize> = match cli.pin.as_deref() {
188	        None => Vec::new(),
189	        // A spec naming a config profile expands to its core list;
190	        // anything else parses as a raw core spec.
191	        Some(spec) => match pin::parse_cores(config.resolve_pin(spec)) {
192	            Ok(v) => v,
193	            Err(e) => {
194	                eprintln!("error: --pin: {e}");
195	                std::process::exit(2);
196	            }
197	        },
198	    };
199	
200	    // Pin main for calibration. Always pinned by default so
201	    // framing/loop numbers come from a stable environment
202	    // regardless of --pin. --no-pin-cal restores pre-0.6.0
203	    // behavior (pin iff --pin given).
204	    //
205	    // When we're doing the cal-only pin (--pin absent, --no-pin-cal
206	    // absent), snapshot the pre-cal affinity and restore it after
207	    // calibrate() so the scheduler regains freedom to co-locate
208	    // bench threads — otherwise main's pin leaks into the
209	    // scheduler's placement decisions and suppresses the
210	    // "both ends hot and spinning" fast path.
211	    let cal_pin: Option<usize> = if cli.no_pin_cal {
212	        None
213	    } else {
214	        pin_cores.first().copied().or(Some(0))
215	    };
216	    // Save/restore pre-cal affinity whenever we're about to set a
217	    // cal pin that wasn't the user's explicit bench-pin request —
218	    // i.e. the cal-only pin (--pin absent, --no-pin-cal absent).
219	    // --pin ⇒ user already wants main on pin[0]; leave alone.
220	    // --no-pin-cal ⇒ we aren't pinning at all; nothing to save.
221	    let saved_affinity = if pin_cores.is_empty() && !cli.no_pin_cal {
222	        pin::save_affinity()
223	    } else {
224	        None
225	    };
226	    pin::pin_current(cal_pin);
227	
228	    if let Some(cpu) = cal_pin {
229	        info!("pinned main to core {cpu} for calibration");
230	    } else {
231	        info!("cal pin skipped");
232	    }
233	    if let Some(mask) = pin::current_affinity() {
234	        debug!("affinity during cal: {}", pin::affinity_summary(&mask));
235	    }
236	
237	    let amp_coeff = overhead::N_HIGH as f64 / (overhead::N_HIGH - overhead::N_LOW) as f64;
238	    info!(
239	        "calibration params: warmup={}, samples={}, N_LOW={}, N_HIGH={}, noise_amp={:.4}",
240	        overhead::CAL_WARMUP,
241	        overhead::CAL_SAMPLES,
242	        overhead::N_LOW,
243	        overhead::N_HIGH,
244	        amp_coeff,
245	    );
246	
247	    let overhead = overhead::calibrate();
248	
249	    debug!(
250	        "calibration raw: min_low={} ns, min_high={} ns",
251	        overhead.cal_min_low_ns, overhead.cal_min_high_ns,
252	    );
253	    debug!(
254	        "calibration fit: framing={:.4} ns, loop_per_iter={:.4} ns",
255	        overhead.framing_per_sample_ns, overhead.loop_per_iter_ns,
256	    );
257	    info!(
258	        "calibration wall time: {:.2} ms",
259	        overhead.cal_duration.as_secs_f64() * 1000.0
260	    );
261	
262	    if let Some(set) = saved_affinity.as_ref() {
263	        pin::restore_affinity(set);
264	    }
265	
266	    let cal_pin_display = match (pin_cores.first(), cli.no_pin_cal) {
267	        (_, true) => "none (--no-pin-cal)".to_string(),
268	        (Some(c), false) => format!("core {c} (from --pin)"),
269	        (None, false) => "core 0 (unpinned after cal; --no-pin-cal to skip)".to_string(),
270	    };
271	    println!("Calibration:");
272	    println!(
273	        "  framing/sample    {:>7} ns  (timer pair, two-point fit)",
274	        harness::fmt_commas_f64(overhead.framing_per_sample_ns, 2)
275	    );
276	    println!(
277	        "  loop/iter         {:>7} ns  (per inner-loop iteration)",
278	        harness::fmt_commas_f64(overhead.loop_per_iter_ns, 2)
279	    );
280	    println!("  cal pin           {cal_pin_display}");
281	    println!("  bench pin         {}", pin::plan_summary(&pin_cores));
282	    println!("  sleep inhibit     {inhibit_status}");
283	    println!("  config            {}", config_summary(&config_files));
284	    println!();
285	
286	    let runners = match benches::resolve(&cli.benches) {
287	        Ok(r) => r,
288	        Err(e) => {
289	            eprintln!("error: {e}");
290	            std::process::exit(2);
291	        }
292	    };
293	
294	    // Duration precedence: CLI -d / -D win, then the config
295	    // `duration`, then the built-in default.
296	    let target_seconds = match (cli.duration, cli.total_duration) {
297	        (Some(d), _) => d,
298	        (None, Some(t)) => t / runners.len() as f64,
299	        (None, None) => config.duration.unwrap_or(DEFAULT_DURATION),
300	    };
301	
302	    let cfg = harness::RunCfg {
303	        overhead: &overhead,
304	        target_seconds,
305	        outer_override: cli.outer,
306	        inner_override: cli.inner,
307	        pin_cores: &pin_cores,
308	        report_ticks: cli.ticks,
309	        band_labels: cli
310	            .band_labels
311	            .or(config.band_labels)
312	            .unwrap_or(DEFAULT_BAND_LABELS),
313	        decimals: cli.decimals.or(config.decimals).unwrap_or(DEFAULT_DECIMALS) as usize,
314	    };
315	
316	    for run in runners {
317	        run(&cfg);
318	    }
319	}
