use clap::Parser;
use log::{debug, info};

#[derive(Parser)]
#[command(
    version,
    about = concat!(
        "iiac-perf ",
        env!("CARGO_PKG_VERSION"),
        " — Rust latency microbenchmark harness",
    ),
