1	//! Free-form measurement probe: a named, single-writer histogram
2	//! of sample durations in nanoseconds.
3	//!
4	//! The caller captures endpoints with any time source (typically
5	//! `minstant::Instant::now()`) and feeds the elapsed delta to
6	//! [`Probe::record`]. At report time [`Probe::report`] renders a
7	//! band-table summary under the enclosing bench's report, using
8	//! the same percentile boundaries so columns line up visually.
9	
10	use hdrhistogram::Histogram;
11	
12	use crate::harness::{fmt_commas, fmt_commas_f64};
13	
14	const BOUNDARY_PCTS: &[f64] = &[
15	    0.0, 0.01, 0.10, 0.20, 0.30, 0.40, 0.50, 0.60, 0.70, 0.80, 0.90, 0.99, 1.0,
16	];
17	const BOUNDARY_NAMES: &[&str] = &[
18	    "min", "p1", "p10", "p20", "p30", "p40", "p50", "p60", "p70", "p80", "p90", "p99", "max",
19	];
20	
21	/// Trimmed-stat range label from the populated bands below the
22	/// `p99-max` tail (`band_count`'s last band).
23	///
24	/// - Names the first..last populated non-tail band low-to-high like
25	///   the rows (`min-p99`, or `p10-p99` / `min-p90` when an end band
26	///   is empty), so the label tracks the real extent instead of a
27	///   fixed `min-p99` whose `min`/`p99` edges may not be present.
28	/// - Empty string when no non-tail band is populated (the caller
29	///   guards this with `trim_count > 0`, so the label goes unused).
30	fn trim_range_label(band_count: &[u64]) -> String {
31	    let trim_end = band_count.len() - 1; // exclude the p99-max tail band
32	    let first = (0..trim_end).find(|&i| band_count[i] > 0);
33	    let last = (0..trim_end).rev().find(|&i| band_count[i] > 0);
34	    match (first, last) {
35	        (Some(f), Some(l)) => format!("{}-{}", BOUNDARY_NAMES[f], BOUNDARY_NAMES[l + 1]),
36	        _ => String::new(),
37	    }
38	}
39	
40	/// Index of the band containing `mid_rank`, over [`BOUNDARY_PCTS`]
41	/// (`n_bands = BOUNDARY_PCTS.len() - 1`).
42	///
43	/// Right-closed `(lower, upper]` — a rank exactly on a boundary falls
44	/// in the band that boundary caps, mirroring
45	/// [`crate::harness::print_report`]'s convention. `mid_rank` is the
46	/// Hazen plotting position `(i - 0.5) / n`.
47	fn band_index(mid_rank: f64) -> usize {
48	    let n_bands = BOUNDARY_PCTS.len() - 1;
49	    BOUNDARY_PCTS[1..]
50	        .iter()
51	        .position(|&b| mid_rank <= b)
52	        .unwrap_or(n_bands - 1)
53	}
