55	/// A named, single-writer nanosecond histogram. Not `Sync`;
56	/// cross-thread *sharing* is out of scope. `Send` so probes can
57	/// be moved between threads (e.g. returned via a
58	/// `JoinHandle<Probe>` on shutdown).
59	pub struct Probe {
60	    name: String,
61	    hist: Histogram<u64>,
62	}
63	
64	impl Probe {
65	    /// Create an empty probe. Histogram bounds (1 ns — 60 s,
66	    /// 3 significant figures) mirror the harness.
67	    ///
68	    /// Exits the process (code 1) if the hardware tick counter
69	    /// isn't usable — see [`crate::ticks::require_ok`].
70	    pub fn new(name: &str) -> Self {
71	        crate::ticks::require_ok();
72	        Self {
73	            name: name.to_string(),
74	            hist: Histogram::<u64>::new_with_bounds(1, 60_000_000_000, 3).unwrap(),
75	        }
76	    }
77	
78	    /// Record a single sample. Values of 0 are clamped to 1 since
79	    /// the histogram's lower bound is 1 ns; sub-ns deltas from
80	    /// coarse timers round up rather than panic.
81	    pub fn record(&mut self, ns: u64) {
82	        self.hist.record(ns.max(1)).unwrap();
83	    }
84	
85	    /// Render a band-table report for this probe, indented one
86	    /// level deeper than the enclosing bench's report. No
87	    /// `adjusted` column — probe overhead subtraction is a
88	    /// separate concern. Bands are right-closed `(lower, upper]`
89	    /// (see [`band_index`]), matching the harness report.
90	    pub fn report(&self) {
91	        let sample_count = self.hist.len();
92	        println!(
93	            "  probe: {} [count={}]",
94	            self.name,
95	            fmt_commas(sample_count)
96	        );
97	        if sample_count == 0 {
98	            println!();
99	            return;
100	        }
101	
102	        let n_bands = BOUNDARY_PCTS.len() - 1;
103	        let mut band_first = vec![u64::MAX; n_bands];
104	        let mut band_last = vec![0u64; n_bands];
105	        let mut band_count = vec![0u64; n_bands];
106	        let mut band_sum = vec![0u128; n_bands];
107	
108	        let mut cumulative = 0u64;
109	        for iv in self.hist.iter_recorded() {
110	            let value = iv.value_iterated_to();
111	            let count = iv.count_at_value();
112	            let mid_rank = (cumulative as f64 + count as f64 / 2.0) / sample_count as f64;
113	            let idx = band_index(mid_rank);
114	            band_first[idx] = band_first[idx].min(value);
115	            band_last[idx] = band_last[idx].max(value);
116	            band_count[idx] += count;
117	            band_sum[idx] += value as u128 * count as u128;
118	            cumulative += count;
119	        }
120	
121	        struct BandRow {
122	            label: String,
123	            first: String,
124	            last: String,
125	            range: String,
126	            count: String,
127	            mean: String,
128	        }
129	
130	        let mut rows: Vec<BandRow> = Vec::new();
131	        for i in 0..n_bands {
132	            if band_count[i] == 0 {
133	                continue;
134	            }
135	            let mean_val = band_sum[i] as f64 / band_count[i] as f64;
136	            rows.push(BandRow {
137	                label: format!("{}-{}", BOUNDARY_NAMES[i], BOUNDARY_NAMES[i + 1]),
138	                first: fmt_commas(band_first[i]),
139	                last: fmt_commas(band_last[i]),
140	                range: fmt_commas(band_last[i] - band_first[i] + 1),
141	                count: fmt_commas(band_count[i]),
142	                mean: fmt_commas_f64(mean_val, 0),
143	            });
144	        }
145	
146	        // Trimmed-stat range label, derived from the populated bands
147	        // (empty when none — then `trim_count > 0` skips the rows).
148	        let trim_range = trim_range_label(&band_count);
149	        let mean_trim_label = format!("mean {trim_range}");
150	        let stdev_trim_label = format!("stdev {trim_range}");
151	
152	        let label_w = rows
153	            .iter()
154	            .map(|r| r.label.len())
155	            .max()
156	            .unwrap_or(0)
157	            .max(stdev_trim_label.len());
158	        let first_w = rows.iter().map(|r| r.first.len()).max().unwrap_or(0);
159	        let last_w = rows.iter().map(|r| r.last.len()).max().unwrap_or(0);
160	        let range_w = rows.iter().map(|r| r.range.len()).max().unwrap_or(0);
161	        let count_w = rows.iter().map(|r| r.count.len()).max().unwrap_or(0);
162	        let mean_w = rows.iter().map(|r| r.mean.len()).max().unwrap_or(0);
163	
164	        const INDENT: &str = "    ";
165	        const GAP: &str = "    ";
166	
167	        let first_col = INDENT.len() + label_w + 1 + first_w;
168	        let last_gap = " ns".len() + GAP.len() + last_w;
169	        let range_gap = " ns".len() + GAP.len() + range_w;
170	        let count_gap = " ns".len() + GAP.len() + count_w;
171	        let mean_gap = GAP.len() + mean_w;
172	        println!(
173	            "{:>first_col$}{:>last_gap$}{:>range_gap$}{:>count_gap$}{:>mean_gap$}",
174	            "first", "last", "range", "count", "mean",
175	        );
176	
177	        for r in &rows {
178	            println!(
179	                "{INDENT}{:<label_w$} {:>first_w$} ns{GAP}{:>last_w$} ns{GAP}{:>range_w$} ns{GAP}{:>count_w$}{GAP}{:>mean_w$} ns",
180	                r.label, r.first, r.last, r.range, r.count, r.mean,
181	            );
182	        }
183	
184	        let hist_mean = self.hist.mean();
185	        let skip = first_w
186	            + " ns".len()
187	            + GAP.len()
188	            + last_w
189	            + " ns".len()
190	            + GAP.len()
191	            + range_w
192	            + " ns".len()
193	            + GAP.len()
194	            + count_w;
195	        println!(
196	            "{INDENT}{:<label_w$} {:>skip$}{GAP}{:>mean_w$} ns",
197	            "mean",
198	            "",
199	            fmt_commas_f64(hist_mean, 0),
200	        );
201	        println!(
202	            "{INDENT}{:<label_w$} {:>skip$}{GAP}{:>mean_w$} ns",
203	            "stdev",
204	            "",
205	            fmt_commas_f64(self.hist.stdev(), 0),
206	        );
207	
208	        let trim_count: u64 = band_count[..n_bands - 1].iter().sum();
209	        if trim_count > 0 {
210	            let trim_sum: u128 = band_sum[..n_bands - 1].iter().sum();
211	            let trim_mean = trim_sum as f64 / trim_count as f64;
212	
213	            let mut trim_var_sum = 0.0f64;
214	            let mut trim_var_count = 0u64;
215	            let mut cum = 0u64;
216	            for iv in self.hist.iter_recorded() {
217	                let value = iv.value_iterated_to();
218	                let count = iv.count_at_value();
219	                let mid_rank = (cum as f64 + count as f64 / 2.0) / sample_count as f64;
220	                let idx = band_index(mid_rank);
221	                if idx < n_bands - 1 {
222	                    let diff = value as f64 - trim_mean;
223	                    trim_var_sum += diff * diff * count as f64;
224	                    trim_var_count += count;
225	                }
226	                cum += count;
227	            }
228	            let trim_stdev = if trim_var_count > 1 {
229	                (trim_var_sum / trim_var_count as f64).sqrt()
230	            } else {
231	                0.0
232	            };
233	
234	            println!(
235	                "{INDENT}{:<label_w$} {:>skip$}{GAP}{:>mean_w$} ns",
236	                mean_trim_label,
237	                "",
238	                fmt_commas_f64(trim_mean, 0),
239	            );
240	            println!(
241	                "{INDENT}{:<label_w$} {:>skip$}{GAP}{:>mean_w$} ns",
242	                stdev_trim_label,
243	                "",
244	                fmt_commas_f64(trim_stdev, 0),
